tol = 1e-7
nodes = np.where(dsl > tol)[0] + 1  # node indices with a slope change

# group consecutive nodes into clusters (one boundary can straddle a
# grid interval, producing two adjacent slope-change nodes)
clusters = []
if len(nodes):
    start = prev = nodes[0]
    for nn in nodes[1:]:
        if nn == prev + 1:
            prev = nn
        else:
            clusters.append((start, prev))
            start = prev = nn
    clusters.append((start, prev))

for lo, hi in clusters:
    # skip wide clusters (two boundaries too close) and edges
    if hi - lo > 2 or lo < 2 or hi > N - 3:
        continue
    gl = grad(x0 + ts[lo - 1] * d)
    gr = grad(x0 + ts[hi + 1] * d)
